
// 微信小程序 Polyfills
// 用于兼容 supabase-js 等依赖标准 Web API 的库

const installPolyfills = () => {
  console.log('[Polyfill] Installing Supabase polyfills for WeChat Mini Program...')

  // ==========================================
  // 1. URL Polyfill
  // ==========================================
  class WechatURL {
    constructor(url, base) {
      let fullUrl = url;
      if (base && !url.startsWith('http')) {
         fullUrl = (base.endsWith('/') ? base : base + '/') + (url.startsWith('/') ? url.slice(1) : url);
      }
      this.href = fullUrl;
      
      const protocolMatch = fullUrl.match(/^(https?:)\/\//);
      this.protocol = protocolMatch ? protocolMatch[1] : 'https:';
      
      const remaining = protocolMatch ? fullUrl.slice(protocolMatch[0].length) : fullUrl;
      const pathStart = remaining.indexOf('/');
      const hostPart = pathStart === -1 ? remaining : remaining.slice(0, pathStart);
      
      const portMatch = hostPart.match(/:(\d+)$/);
      this.port = portMatch ? portMatch[1] : '';
      this.hostname = portMatch ? hostPart.slice(0, portMatch.index) : hostPart;
      this.host = hostPart;
      this.origin = this.protocol + '//' + this.host;
      this.pathname = pathStart === -1 ? '/' : remaining.slice(pathStart).split('?')[0];
      
      const searchStart = fullUrl.indexOf('?');
      this.search = searchStart === -1 ? '' : fullUrl.slice(searchStart);
      
      this.searchParams = {
          get: (key) => {
              if (!this.search) return null;
              const match = this.search.slice(1).match(new RegExp('(^|&)' + key + '=([^&]*)'));
              return match ? decodeURIComponent(match[2]) : null;
          }
      };
    }
  }

  // 强制替换全局 URL
  const replaceGlobal = (key, value) => {
    try {
      if (typeof global !== 'undefined') global[key] = value;
      if (typeof window !== 'undefined') window[key] = value;
      if (typeof globalThis !== 'undefined') globalThis[key] = value;
    } catch (e) {
      console.warn(`[Polyfill] Failed to set global.${key}:`, e);
    }
  };

  replaceGlobal('URL', WechatURL);

  // ==========================================
  // 2. WebSocket Polyfill
  // ==========================================
  class WechatWebSocket {
    constructor(url, protocols) {
      this.url = url;
      this.protocols = protocols;
      this.readyState = WechatWebSocket.CONNECTING;
      
      this.onopen = null;
      this.onmessage = null;
      this.onerror = null;
      this.onclose = null;
      
      this._socketTask = uni.connectSocket({
        url: url,
        protocols: Array.isArray(protocols) ? protocols : [],
        success: () => {},
        fail: (res) => {
          this._emitError(new Error(res.errMsg));
        }
      });
      
      this._socketTask.onOpen((res) => {
        this.readyState = WechatWebSocket.OPEN;
        if (this.onopen) this.onopen({ target: this });
      });
      
      this._socketTask.onMessage((res) => {
        if (this.onmessage) this.onmessage({ data: res.data, target: this });
      });
      
      this._socketTask.onError((res) => {
        this._emitError(new Error(res.errMsg));
      });
      
      this._socketTask.onClose((res) => {
        this.readyState = WechatWebSocket.CLOSED;
        // 拦截 1006 状态码
        let code = res.code;
        if (code === 1006) code = 1000;
        
        if (this.onclose) this.onclose({ code: code, reason: res.reason, target: this });
      });
    }
    
    _emitError(error) {
      if (this.onerror) this.onerror({ error: error, message: error.message, target: this });
    }
    
    send(data) {
      if (this.readyState === WechatWebSocket.OPEN) {
        this._socketTask.send({ data });
      }
    }
    
    close(code, reason) {
      this.readyState = WechatWebSocket.CLOSING;
      let validCode = code;
      if (validCode === 1006) validCode = 1000;
      if (validCode && (validCode !== 1000 && (validCode < 3000 || validCode > 4999))) {
          validCode = null;
      }
      
      const opts = {};
      if (validCode) opts.code = validCode;
      if (reason) opts.reason = reason;
      
      this._socketTask.close(opts);
    }
  }

  WechatWebSocket.CONNECTING = 0;
  WechatWebSocket.OPEN = 1;
  WechatWebSocket.CLOSING = 2;
  WechatWebSocket.CLOSED = 3;

  replaceGlobal('WebSocket', WechatWebSocket);

  // ==========================================
  // 3. Fetch Polyfill (Global)
  // ==========================================
  // 虽然 Supabase 允许配置 fetch，但为了保险，全局也 patch 一下
  const wechatFetch = (url, options = {}) => {
    return new Promise((resolve, reject) => {
      uni.request({
        url: url,
        method: options.method || 'GET',
        data: options.body,
        header: options.headers,
        dataType: 'text', // 默认按文本接收，自行 parse，避免 uni-app 自动转换带来的不一致
        success: (res) => {
          resolve({
            ok: res.statusCode >= 200 && res.statusCode < 300,
            status: res.statusCode,
            statusText: res.errMsg,
            headers: {
              get: (key) => res.header[key] || res.header[key.toLowerCase()]
            },
            json: () => {
                try {
                    return Promise.resolve(typeof res.data === 'string' ? JSON.parse(res.data) : res.data);
                } catch(e) {
                    return Promise.reject(e);
                }
            },
            text: () => Promise.resolve(typeof res.data === 'string' ? res.data : JSON.stringify(res.data)),
            blob: () => Promise.resolve(res.data) // 简单 mock
          })
        },
        fail: (err) => {
          reject(new Error(err.errMsg || 'Network request failed'))
        }
      })
    })
  }
  
  replaceGlobal('fetch', wechatFetch);
  replaceGlobal('Headers', class Headers { constructor(init) { this.map = init || {}; } append(k, v) { this.map[k] = v; } get(k) { return this.map[k]; } });
  
  console.log('[Polyfill] Installation complete.');
};

installPolyfills();
